mapper.sql:
history.user_id = #{userId}

    AND history.amount > 0


    AND history.amount < 0


    AND history.created_at >= #{startDate}


    AND (
        history.description LIKE CONCAT('%', #{keyword}, '%')
        OR history.type LIKE CONCAT('%', #{keyword}, '%')
        OR history.reference_key LIKE CONCAT('%', #{keyword}, '%')
    )
